-- Free-licence food photos (Openverse: Wikimedia Commons / Flickr), each checked by eye to show that exact food.
-- Run once in Supabase → SQL Editor. Safe to run again.
alter table public.food_photos add column if not exists licence text;
alter table public.food_photos add column if not exists licence_url text;
on conflict (key) do update set url = excluded.url, author = excluded.author, author_url = excluded.author_url, photo_page = excluded.photo_page, licence = excluded.licence, licence_url = excluded.licence_url, verified = true, tried_at = now();
